function detail(id){const d=modes[mode].details[id];el('detail-tag').textContent=d[0];el('detail-title').textContent=d[1];el('detail-text').textContent=d[2];document.querySelectorAll('[data-node]').forEach(b=>{b.classList.toggle('chosen',b.dataset.node===id);b.setAttribute('aria-pressed',b.dataset.node===id)})}
function renderTrace(){const list=traces();step=Math.min(step,list.length-1);const t=list[step];el('trace-progress').innerHTML=list.map((_,i)=>`<span class="${i<=step?'active':''}"></span>`).join('');el('trace-number').textContent='STEP '+String(step+1).padStart(2,'0');el('trace-title').textContent=t[0];el('trace-text').textContent=t[1];el('trace-count').textContent=`${step+1} / ${list.length}`;el('prev').disabled=step===0;el('next').disabled=step===list.length-1;el('payload-label').textContent=mode==='native'?'REQUIRED CONTRACT':'PROPOSED TRACE';el('payload-code').textContent=JSON.stringify(t[2],null,2);}
function renderMode(){const m=modes[mode];el('mode-kicker').textContent=m.kicker;el('architecture-title').textContent=m.title;el('runtime-label').textContent=m.runtime;el('owner').textContent=m.owner;el('owner-note').textContent=m.ownerNote;el('runtime-diagram').innerHTML=m.diagram();el('build-title').textContent=m.buildTitle;el('build-status').textContent=m.status;el('build-status').className='status '+m.statusClass;el('build-steps').innerHTML=m.steps.map(([title,body],i)=>`<article class="build-step"><span>0${i+1}</span><h3>${title}</h3><p>${body}</p></article>`).join('');el('limitation-text').textContent=m.limitation;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===mode);b.setAttribute('aria-pressed',b.dataset.mode===mode)});document.querySelectorAll('[data-node]').forEach(b=>b.addEventListener('click',()=>detail(b.dataset.node)));detail(Object.keys(m.details)[1]);renderTrace();}
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{mode=b.dataset.mode;step=0;renderMode()}));
el('situation').addEventListener('change',e=>{situation=e.target.value;step=0;renderTrace()});el('prev').addEventListener('click',()=>{step=Math.max(0,step-1);renderTrace()});el('next').addEventListener('click',()=>{step=Math.min(traces().length-1,step+1);renderTrace()});renderMode();
